package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for SimpleType.construct(Class<?> cls)
 */
public class SimpleType_construct_TriageGen1Test {

    @Test
    public void testConstruct_ValidClass() {
        Class<?> validClass = String.class;
        SimpleType result = SimpleType.construct(validClass);

        assertNotNull("Result should not be null", result);
        assertEquals("The class should match the input class", validClass, result.getRawClass());
    }

    @Test
    public void testConstruct_IntegerClass() {
        Class<?> validClass = Integer.class;
        SimpleType result = SimpleType.construct(validClass);

        assertNotNull(result);
        assertEquals(validClass, result.getRawClass());
    }

    @Test
    public void testConstruct_MapThrowsException() {
        // Testing Map.class directly
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(Map.class);
        });
        assertEquals("Can not construct SimpleType for a Map (class: java.util.Map)", exception.getMessage());

        // Testing a subclass of Map
        IllegalArgumentException exceptionSubclass = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(HashMap.class);
        });
        assertEquals("Can not construct SimpleType for a Map (class: java.util.HashMap)", exceptionSubclass.getMessage());
    }

    @Test
    public void testConstruct_CollectionThrowsException() {
        // Testing Collection.class directly
        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(Collection.class);
        });
        assertEquals("Can not construct SimpleType for a Collection (class: java.util.Collection)", exception.getMessage());

        // Testing a subclass of Collection
        IllegalArgumentException exceptionSubclass = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(List.class);
        });
        assertEquals("Can not construct SimpleType for a Collection (class: java.util.List)", exceptionSubclass.getMessage());
    }

    @Test
    public void testConstruct_ArrayThrowsException() {
        // Testing primitive array
        IllegalArgumentException exceptionPrimitive = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(int[].class);
        });
        assertEquals("Can not construct SimpleType for an array (class: [I)", exceptionPrimitive.getMessage());

        // Testing object array
        IllegalArgumentException exceptionObject = assertThrows(IllegalArgumentException.class, () -> {
            SimpleType.construct(String[].class);
        });
        assertEquals("Can not construct SimpleType for an array (class: [Ljava.lang.String;)", exceptionObject.getMessage());
    }

    @Test
    public void testConstruct_CustomObject() {
        class CustomObject {}
        SimpleType result = SimpleType.construct(CustomObject.class);
        assertNotNull(result);
        assertEquals(CustomObject.class, result.getRawClass());
    }
}
